import{_ as n,a0 as o,w as l,s as r,ao as d,I as p,x as t,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"如何為 APT 命令設置代理 | LCTT x X-CMD","titleTemplate":false,"description":"如何為 APT 命令設置代理 | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何為 APT 命令設置代理 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何為 APT 命令設置代理 | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230422.0 ⭐️ How to Set Proxy Settings for APT Command","title":"如何為 APT 命令設置代理","tag":"202305","desc":""},"relativePath":"202305/20230422.0 ⭐️ How to Set Proxy Settings for APT Command.md","filePath":"[post].md"}'),h={name:"202305/20230422.0 ⭐️ How to Set Proxy Settings for APT Command.md"};function c(g,s,u,k,b,f){const a=o("Link");return l(),r("div",null,[s[15]||(s[15]=d(`<h1 id="如何為-apt-命令設置代理" tabindex="-1">如何為 APT 命令設置代理 <a class="header-anchor" href="#如何為-apt-命令設置代理" aria-label="Permalink to “如何為 APT 命令設置代理”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202305/15/184447hh8ac86hkycy6jio.jpg" alt=""></p><blockquote><p>在本指南中，你將瞭解如何在 Ubuntu/Debian Linux 發行版中為 <code>apt</code> 命令設置代理。</p></blockquote><p>代理服務器是位於請求資源的客户端系統或最終用户與資源本身之間的中間服務器。在大多數情況下，代理服務器充當最終用户和互聯網之間的網關。</p><p>對於組織和企業環境，代理服務器提供了許多好處。它通過阻止被認為會影響員工工作效率的網站來控制互聯網的使用。它還通過數據加密增強隱私並提高組織的安全性。</p><p>有幾種方法可以為 <code>apt</code> 命令設置代理，讓我們直接進入。</p><p>注意：為了演示，我們將使用 Ubuntu 22.04。</p><h3 id="使用代理文件為-apt-配置代理" tabindex="-1">使用代理文件為 APT 配置代理 <a class="header-anchor" href="#使用代理文件為-apt-配置代理" aria-label="Permalink to “使用代理文件為 APT 配置代理”">​</a></h3><p>為 <code>apt</code> 命令配置代理的最簡單方法是創建一個 <code>proxy.conf</code> 文件，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/apt/apt.conf.d/proxy.conf</span></span></code></pre></div><p>對於沒有用户名和密碼的代理服務器，添加以下條目，如下：</p><p>對於 HTTP 代理，添加以下條目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Acquire::http::Proxy &quot;http://proxy-IP-address:proxyport/&quot;;</span></span></code></pre></div><p>對 HTTPS 代理執行相同的操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Acquire::https::Proxy &quot;http://proxy-IP-address:proxyport/&quot;;</span></span></code></pre></div><p>例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat  /etc/apt/apt.conf.d/proxy.conf</span></span>
<span class="line"><span>Acquire::http::Proxy &quot;http://192.168.56.102:3128/&quot;;</span></span>
<span class="line"><span>Acquire::https::Proxy &quot;http://192.168.56.102:3128/&quot;;</span></span></code></pre></div><p>如果你的代理服務器需要用户名和密碼詳細信息，請按以下方式添加：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Acquire::http::Proxy &quot;http://username:password@proxy-IP-address:proxyport&quot;;</span></span>
<span class="line"><span>Acquire::https::Proxy &quot;http://username:password@proxy-IP-address:proxyport&quot;;</span></span></code></pre></div><p>例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat  /etc/apt/apt.conf.d/proxy.conf</span></span>
<span class="line"><span>Acquire::http::Proxy &quot;http://init@PassW0rd321#@192.168.56.102:3128/&quot;;</span></span>
<span class="line"><span>Acquire::https::Proxy &quot;http://init@PassW0rd321#@192.168.56.102:3128/&quot;;</span></span></code></pre></div><p>完成後，保存更改並退出配置文件。代理設置將在你下次運行 APT 包管理器時生效。</p><p>例如，你可以更新本地包索引，然後安裝 <code>net-tools</code> 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span>
<span class="line"><span>$ sudo apt install net-tools -y</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Apt-Install-Package-Proxy-Settings-1024x403.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>驗證代理服務器日誌以確認 <code>apt</code> 命令正在使用代理服務器下載包。在代理服務器運行時：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tail -f /var/log/squid/access.log  | grep -i 192.168.56.240</span></span></code></pre></div><p>這裏 <code>192.168.56.240</code> 是我們 Ubuntu 機器的 IP 地址。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Grep-Proxy-Logs-Ubuntu-Machine-1024x326.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>完美，上面的輸出確認我們的 Ubuntu 系統的 <code>apt</code> 命令正在通過代理服務器（192.168.56.102）下載包。</p><h3 id="另一種指定代理詳細信息的方法" tabindex="-1">另一種指定代理詳細信息的方法 <a class="header-anchor" href="#另一種指定代理詳細信息的方法" aria-label="Permalink to “另一種指定代理詳細信息的方法”">​</a></h3><p>除了第一種方法，你還可以用更簡單的方式指定代理詳細信息。再次創建一個 <code>proxy.conf</code> 文件，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/apt/apt.conf.d/proxy.conf</span></span></code></pre></div><p>對於沒有用户名和密碼的代理服務器，如圖所示進行定義。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Acquire {</span></span>
<span class="line"><span>  http::Proxy &quot;http://proxy-IP-address:proxyport/&quot;;</span></span>
<span class="line"><span>  https::Proxy &quot;http://proxy-IP-address:proxyport/&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>示例文件如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/apt/apt.conf.d/proxy.conf</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Proxy-conf-Apt-Command-Ubuntu.png" alt=""></p><p>對於具有用户名和登錄詳細信息的代理服務器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Acquire {</span></span>
<span class="line"><span>   http::Proxy &quot;http://username:password@proxy-IP-address:proxyport/&quot;;</span></span>
<span class="line"><span>   https::Proxy &quot;http://username:password@proxy-IP-address:proxyport/&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>保存更改並退出配置文件。提醒一下，當你開始使用 APT 包管理器，這些設置就會立即生效。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>本指南到此結束。在本教程中，我們演示瞭如何為 Debian/Ubuntu Linux 發行版中使用的 APT 包管理器配置代理設置。本文就到這裏了。</p><p>（題圖：MJ/dfb4d5a0-9150-47bd-9f54-c120ddd77046）</p><hr>`,45)),p("p",null,[s[1]||(s[1]=t("via: ",-1)),i(a,{href:"https://www.linuxtechi.com/set-proxy-settings-for-apt-command/"},{default:e(()=>[...s[0]||(s[0]=[t("https://www.linuxtechi.com/set-proxy-settings-for-apt-command/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=t("作者：",-1)),i(a,{href:"https://www.linuxtechi.com/author/james/"},{default:e(()=>[...s[2]||(s[2]=[t("James Kiarie",-1)])]),_:1}),s[7]||(s[7]=t(" 選題：",-1)),i(a,{href:"https://github.com/lkxed/"},{default:e(()=>[...s[3]||(s[3]=[t("lkxed",-1)])]),_:1}),s[8]||(s[8]=t(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:e(()=>[...s[4]||(s[4]=[t("geekpi",-1)])]),_:1}),s[9]||(s[9]=t(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[t("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[t("LCTT",-1)])]),_:1}),s[13]||(s[13]=t(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[t("Linux中國",-1)])]),_:1}),s[14]||(s[14]=t(" 榮譽推出",-1))])])}const P=n(h,[["render",c]]);export{m as __pageData,P as default};
